{"path": "units/ranges/ranges.py", "content": "class Impl:
    def merge(self, ranges):
        intervals = sorted((min(a, b), max(a, b)) for a, b in ranges)
        merged = []
        for start, end in intervals:
            if merged and start <= merged[-1][1] + 1:
                merged[-1] = (merged[-1][0], max(merged[-1][1], end))
            else:
                merged.append((start, end))
        return merged
"}

{"path": "units/chain/stage1.py", "content": "import csv


def parse_orders(path):
    rows = []
    with open(path, newline="") as fh:
        for row in csv.DictReader(fh):
            rows.append(
                {"id": int(row["id"]), "qty": int(row["qty"]), "price": int(row["price"])}
            )
    return rows
"}

{"path": "units/chain/stage3.py", "content": "def total_by_price(rows):
    totals = {}
    for row in rows:
        totals[row["price"]] = totals.get(row["price"], 0) + row["qty"]
    return totals
"}

